export default function makeController() {
  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
  const MOTOR_TAU = 0.038;
  const DT = 0.01;

  let stepCount = 0;
  let prevObs = null;
  let prevAction = { thrust: 0.45, roll: 0, pitch: 0, yawRate: 0 };

  // Tracked simulator inner attitude integral
  const simInt = { roll: 0, pitch: 0 };

  // Lagged command states
  let lagThrust = 0.45;
  const lagAlpha = { roll: 0, pitch: 0, yaw: 0 };

  // Observers:
  // 1. Thrust scale S = (4 * maxMotorThrust * (1 - w/4)) / mass (nominal ~ 20.0 m/s^2)
  let thrustScale = 20.0;
  let airborneSteps = 0;

  // 2. Torque bias per unit thrust (beta) + residual bias (bRes)
  const beta = { roll: 0, pitch: 0, yaw: 0 };
  const bRes = { roll: 0, pitch: 0, yaw: 0 };

  // 3. Wind disturbance acceleration observers (d = c_d * wind)
  const windFast = { x: 0, z: 0 };
  const windMed = { x: 0, z: 0 };
  const windSlow = { x: 0, z: 0 };

  // Filtered attitude targets for derivative feedforward
  let prevRollDes = 0;
  let prevPitchDes = 0;

  // Navigation state
  let targetGate = -1;
  let phase = 'align';
  let settle = 0;
  let intZ = 0;
  let intY = 0;
  let padPinned = false;

  return {
    step(obs) {
      const p = obs.pos;
      const v = obs.vel;
      const att = obs.att;
      const rates = obs.rates;

      if (prevObs !== null) {
        // 1. Update tracked simulator inner loop integral across 2 substeps
        for (let sub = 0; sub < 2; sub++) {
          const frac = (sub + 0.5) * 0.5;
          const rEst = prevObs.att.roll + frac * (att.roll - prevObs.att.roll);
          const pEst = prevObs.att.pitch + frac * (att.pitch - prevObs.att.pitch);
          simInt.roll = clamp(simInt.roll + (prevAction.roll - rEst) * 0.005, -0.35, 0.35);
          simInt.pitch = clamp(simInt.pitch + (prevAction.pitch - pEst) * 0.005, -0.35, 0.35);
        }

        // Commanded angular accelerations in previous step
        const cmdAlphaRoll = 65 * (prevAction.roll - prevObs.att.roll) - 13 * prevObs.rates.roll + 22 * simInt.roll;
        const cmdAlphaPitch = 65 * (prevAction.pitch - prevObs.att.pitch) - 13 * prevObs.rates.pitch + 22 * simInt.pitch;
        const cmdAlphaYaw = 8 * (prevAction.yawRate - prevObs.rates.yaw);

        const alphaDecay = 1 - Math.exp(-DT / MOTOR_TAU);
        lagThrust += (prevAction.thrust - lagThrust) * alphaDecay;
        lagAlpha.roll += (cmdAlphaRoll - lagAlpha.roll) * alphaDecay;
        lagAlpha.pitch += (cmdAlphaPitch - lagAlpha.pitch) * alphaDecay;
        lagAlpha.yaw += (cmdAlphaYaw - lagAlpha.yaw) * alphaDecay;

        // Measured angular accelerations
        const measAlphaRoll = (rates.roll - prevObs.rates.roll) / DT;
        const measAlphaPitch = (rates.pitch - prevObs.rates.pitch) / DT;
        const measAlphaYaw = (rates.yaw - prevObs.rates.yaw) / DT;

        const resRoll = measAlphaRoll + 0.4 * prevObs.rates.roll - lagAlpha.roll;
        const resPitch = measAlphaPitch + 0.4 * prevObs.rates.pitch - lagAlpha.pitch;
        const resYaw = measAlphaYaw + 0.4 * prevObs.rates.yaw - lagAlpha.yaw;

        if (lagThrust > 0.16 && p.y > 0.085) {
          const gBeta = airborneSteps < 35 ? 0.12 : 0.04;
          beta.roll = clamp(beta.roll + gBeta * (resRoll - beta.roll * lagThrust) / lagThrust, -30, 30);
          beta.pitch = clamp(beta.pitch + gBeta * (resPitch - beta.pitch * lagThrust) / lagThrust, -30, 30);
          beta.yaw = clamp(beta.yaw + gBeta * (resYaw - beta.yaw * lagThrust) / lagThrust, -5, 5);

          bRes.roll = clamp(bRes.roll + 0.03 * (resRoll - beta.roll * lagThrust - bRes.roll), -4, 4);
          bRes.pitch = clamp(bRes.pitch + 0.03 * (resPitch - beta.pitch * lagThrust - bRes.pitch), -4, 4);
          bRes.yaw = clamp(bRes.yaw + 0.03 * (resYaw - beta.yaw * lagThrust - bRes.yaw), -2, 2);
        }

        // 2. Translational observers (when airborne and away from ceiling/floor contact)
        const midRoll = 0.5 * (prevObs.att.roll + att.roll);
        const midPitch = 0.5 * (prevObs.att.pitch + att.pitch);
        const midYaw = 0.5 * (prevObs.att.yaw + att.yaw);

        const bodyX = Math.sin(midPitch) * Math.cos(midRoll);
        const bodyZ = -Math.sin(midRoll);
        const dirX = Math.cos(midYaw) * bodyX + Math.sin(midYaw) * bodyZ;
        const dirY = Math.cos(midPitch) * Math.cos(midRoll);
        const dirZ = -Math.sin(midYaw) * bodyX + Math.cos(midYaw) * bodyZ;

        const estMass = clamp(15.3 / thrustScale, 0.6, 0.95);
        const cd = 0.42 / estMass;

        const measAx = (v.x - prevObs.vel.x) / DT;
        const measAy = (v.y - prevObs.vel.y) / DT;
        const measAz = (v.z - prevObs.vel.z) / DT;

        if (p.y > 0.09 && p.y < 2.88 && prevObs.pos.y > 0.09) {
          airborneSteps++;
          const uEff = lagThrust * dirY;
          if (uEff > 0.22 && prevAction.thrust > 0.05 && prevAction.thrust < 0.96) {
            const impliedS = (measAy + 9.81 + cd * prevObs.vel.y) / uEff;
            const gS = airborneSteps < 30 ? 0.14 : 0.045;
            thrustScale = clamp(thrustScale + gS * (impliedS - thrustScale), 15.0, 27.0);
          }

          // Specific thrust acceleration
          const specThrust = thrustScale * lagThrust;
          const rawWindX = clamp(measAx - specThrust * dirX + cd * prevObs.vel.x, -12, 12);
          const rawWindZ = clamp(measAz - specThrust * dirZ + cd * prevObs.vel.z, -12, 12);

          windFast.x += 0.24 * (rawWindX - windFast.x);
          windFast.z += 0.24 * (rawWindZ - windFast.z);
          windMed.x += 0.08 * (rawWindX - windMed.x);
          windMed.z += 0.08 * (rawWindZ - windMed.z);
          windSlow.x += 0.025 * (rawWindX - windSlow.x);
          windSlow.z += 0.025 * (rawWindZ - windSlow.z);
        }
      }

      stepCount++;
      const estMass = clamp(15.3 / thrustScale, 0.6, 0.95);
      const cd = 0.42 / estMass;

      // Gust transient indicator in Z and X
      const gustDiffZ = windFast.z - windSlow.z;
      const gustDiffX = windFast.x - windSlow.x;
      const gustRateZ = windFast.z - windMed.z;
      const gustRateX = windFast.x - windMed.x;

      let axDes = 0;
      let ayDes = 0;
      let azDes = 0;
      let maxTilt = 0.52;
      let lowThrustPin = false;

      if (obs.gateIndex < 3) {
        padPinned = false;
        const gate = obs.nextGate.centre;
        if (targetGate !== obs.gateIndex) {
          targetGate = obs.gateIndex;
          phase = 'align';
          settle = 0;
          intZ = 0;
          intY = 0;
        }

        const dxGate = gate.x - p.x;
        const dyGate = gate.y - p.y;
        const dzGate = gate.z - p.z;

        // Predict crossing time if moving toward gate
        const tCross = clamp(dxGate / Math.max(0.25, v.x + 0.05), 0.02, 0.32);
        const curAzEst = windFast.z - cd * v.z - 9.81 * Math.sin(att.roll);
        const curAyEst = thrustScale * lagThrust * Math.cos(att.roll) * Math.cos(att.pitch) - 9.81 - cd * v.y;
        const zPred = p.z + v.z * tCross + 0.5 * curAzEst * tCross * tCross;
        const yPred = p.y + v.y * tCross + 0.5 * curAyEst * tCross * tCross;

        // Stopping distance in +x
        const vxPos = Math.max(0, v.x);
        const stopDistX = vxPos * 0.045 + (vxPos * vxPos) / (2 * 3.8);

        if (phase === 'align') {
          const zCentered = Math.abs(dzGate) < 0.015 && Math.abs(v.z) < 0.085 && Math.abs(zPred - gate.z) < 0.019;
          const yCentered = Math.abs(dyGate) < 0.065 && Math.abs(v.y) < 0.22 && Math.abs(yPred - gate.y) < 0.085;
          const xReady = dxGate > 0.06 && dxGate < 0.36;
          const gustCalm = Math.abs(gustRateZ) < 0.85;

          if (zCentered && yCentered && xReady && gustCalm) {
            settle++;
          } else {
            settle = Math.max(0, settle - 1);
          }

          if (settle >= 4) {
            phase = 'lunge';
          }
        } else if (phase === 'lunge') {
          // Check if a gust or alignment drift requires braking before crossing
          const zUnsafe = Math.abs(zPred - gate.z) > 0.022 || Math.abs(dzGate) > 0.023 || Math.abs(gustRateZ) > 1.35;
          const yUnsafe = Math.abs(yPred - gate.y) > 0.095 || Math.abs(dyGate) > 0.095;
          const canBrake = dxGate > stopDistX + 0.015 || (dxGate > 0.05 && v.x < 0.65);

          if ((zUnsafe || yUnsafe) && canBrake) {
            phase = 'align';
            settle = 0;
          }
        }

        // Integrals for tight gate centering
        if (Math.abs(dzGate) < 0.12 && Math.abs(dxGate) < 0.5) {
          intZ = clamp(intZ + dzGate * DT, -0.25, 0.25);
        } else {
          intZ *= 0.95;
        }
        if (Math.abs(dyGate) < 0.20) {
          intY = clamp(intY + dyGate * DT, -0.35, 0.35);
        }

        // Z control (critical 3.5 cm margin!)
        const kpZ = Math.abs(dxGate) < 0.45 ? 12.5 : 8.5;
        const kdZ = Math.abs(dxGate) < 0.45 ? 6.2 : 4.8;
        azDes = kpZ * dzGate - kdZ * v.z + 2.8 * intZ - windFast.z - 0.55 * gustRateZ;
        azDes = clamp(azDes, -5.2, 5.2);

        // Y control (14 cm margin)
        ayDes = 9.0 * dyGate - 4.8 * v.y + 2.2 * intY;
        ayDes = clamp(ayDes, -4.5, 5.5);

        // X control: align vs lunge
        if (phase === 'align') {
          // Keep further back if Z or Y is still far from centered
          const standOff = (Math.abs(dzGate) > 0.06 || Math.abs(dyGate) > 0.14) ? 0.32 : 0.21;
          const targetX = gate.x - standOff;
          const ex = targetX - p.x;
          axDes = 7.5 * ex - 4.6 * v.x - windFast.x - 0.45 * gustRateX;

          // Hard safety barrier so drone NEVER drifts across gate.x while unaligned
          if (dxGate < stopDistX + 0.07 && (Math.abs(dzGate) > 0.018 || Math.abs(dyGate) > 0.08)) {
            axDes = Math.min(axDes, -4.8 - windFast.x);
          }
          axDes = clamp(axDes, -5.0, 4.2);
        } else {
          // Lunge across gate!
          const targetX = gate.x + 0.35;
          const ex = targetX - p.x;
          axDes = clamp(9.5 * ex - 3.8 * v.x + 1.4 - windFast.x - 0.45 * gustRateX, -4.5, 4.8);
        }
      } else {
        // Gate 3 passed -> Land on pad (2.05, 0, 1.65)
        const pad = obs.pad.centre;
        const ex = pad.x - p.x;
        const ez = pad.z - p.z;
        const distXZ = Math.hypot(ex, ez);
        const speedXZ = Math.hypot(v.x, v.z);
        const speed3D = Math.hypot(v.x, v.y, v.z);

        // Check if we can pin to the pad with low thrust
        if (p.y <= 0.088 && distXZ <= 0.135 && speed3D < 0.65) {
          padPinned = true;
        }
        if (padPinned && (distXZ > 0.145 || p.y > 0.11)) {
          padPinned = false;
        }

        if (padPinned) {
          lowThrustPin = true;
          maxTilt = 0.13; // Well below landingTilt = 0.18
          axDes = clamp(8.0 * ex - 4.0 * v.x - 0.7 * windFast.x, -2.0, 2.0);
          azDes = clamp(8.0 * ez - 4.0 * v.z - 0.7 * windFast.z, -2.0, 2.0);
          ayDes = -6.0;
        } else {
          // Approach and descend onto pad
          if (distXZ < 0.12) {
            intZ = clamp(intZ + ez * DT, -0.25, 0.25);
          } else {
            intZ *= 0.95;
          }

          axDes = clamp(7.8 * ex - 4.6 * v.x - windFast.x - 0.45 * gustRateX, -4.5, 4.5);
          azDes = clamp(7.8 * ez - 4.6 * v.z + 2.0 * intZ - windFast.z - 0.45 * gustRateZ, -4.5, 4.5);

          let targetY;
          if (distXZ > 0.11 || (p.y < 0.22 && speedXZ > 0.32)) {
            targetY = clamp(0.18 + 0.65 * distXZ, 0.18, 0.85);
          } else {
            targetY = 0.03;
          }

          const ey = targetY - p.y;
          let vyDes = clamp(3.2 * ey, -0.36, 1.5);
          if (p.y < 0.15 && targetY < 0.10) {
            vyDes = Math.max(vyDes, -0.22); // Gentle touchdown well below 0.85 m/s crash speed
            maxTilt = 0.26; // Keep tilt well below 0.36 rad floor crash limit
          }
          if (p.y < 0.11 && targetY < 0.10) {
            maxTilt = 0.15; // Ready for < 0.18 rad landing hold
          }
          ayDes = clamp(6.0 * (vyDes - v.y), -3.8, 4.8);
        }
      }

      // Compute desired thrust vector in world frame
      const aTx = axDes + cd * v.x;
      const aTz = azDes + cd * v.z;
      const aTy = Math.max(2.0, 9.81 + cd * v.y + ayDes);

      // Rotate horizontal thrust into body yaw frame
      const cy = Math.cos(att.yaw);
      const sy = Math.sin(att.yaw);
      const fx = cy * aTx - sy * aTz;
      const fz = sy * aTx + cy * aTz;
      const aTotal = Math.hypot(fx, aTy, fz);

      let pitchDes = clamp(Math.atan2(fx, aTy), -maxTilt, maxTilt);
      let rollDes = clamp(-Math.asin(clamp(fz / aTotal, -0.6, 0.6)), -maxTilt, maxTilt);

      let thrust;
      if (lowThrustPin) {
        thrust = 0.08;
      } else {
        const cosTilt = Math.max(0.5, Math.cos(att.roll) * Math.cos(att.pitch));
        thrust = clamp(aTy / (thrustScale * cosTilt), 0.05, 1.0);
      }

      // Derivative of desired tilt (clamped to avoid noise spikes)
      const rollRateDes = clamp((rollDes - prevRollDes) / DT, -3.5, 3.5);
      const pitchRateDes = clamp((pitchDes - prevPitchDes) / DT, -3.5, 3.5);
      prevRollDes = rollDes;
      prevPitchDes = pitchDes;

      // Invert inner attitude loop with torque bias compensation
      const kpAtt = 88;
      const kdAtt = 17;
      const alphaRollDes = kpAtt * (rollDes - att.roll) - kdAtt * rates.roll + 11 * rollRateDes;
      const alphaPitchDes = kpAtt * (pitchDes - att.pitch) - kdAtt * rates.pitch + 11 * pitchRateDes;

      const biasRoll = beta.roll * thrust + bRes.roll;
      const biasPitch = beta.pitch * thrust + bRes.pitch;
      const biasYaw = beta.yaw * thrust + bRes.yaw;

      const uAlphaRoll = alphaRollDes + 0.4 * rates.roll - biasRoll;
      const uAlphaPitch = alphaPitchDes + 0.4 * rates.pitch - biasPitch;

      const rollCmd = clamp(att.roll + (uAlphaRoll + 13 * rates.roll - 22 * simInt.roll) / 65.165, -0.6, 0.6);
      const pitchCmd = clamp(att.pitch + (uAlphaPitch + 13 * rates.pitch - 22 * simInt.pitch) / 65.165, -0.6, 0.6);

      // Yaw control with torque bias inversion
      const alphaYawDes = -14 * att.yaw - 5.5 * rates.yaw;
      const yawRateCmd = clamp(rates.yaw + (alphaYawDes + 0.4 * rates.yaw - biasYaw) / 8, -2, 2);

      const action = {
        thrust,
        roll: rollCmd,
        pitch: pitchCmd,
        yawRate: yawRateCmd,
      };

      prevObs = obs;
      prevAction = action;
      return action;
    },
  };
}

