      const yawRateCmd = clamp(rates.yaw + (alphaYawDes + 0.4 * rates.yaw - biasYaw) / 8, -2, 2);

      const action = {
        thrust,
        roll: rollCmd,
        pitch: pitchCmd,
        yawRate: yawRateCmd,
      };

      prevObs = obs;
      prevAction = action;
      return action;
    },
  };
