          const standOff = (Math.abs(dzGate) > 0.06 || Math.abs(dyGate) > 0.14) ? 0.32 : 0.21;
          const targetX = gate.x - standOff;
          const ex = targetX - p.x;
          axDes = 7.5 * ex - 4.6 * v.x - windFast.x - 0.45 * gustRateX;

