            axDes = Math.min(axDes, -4.8 - windFast.x);
          }
          axDes = clamp(axDes, -5.0, 4.2);
        } else {
          const targetX = gate.x + 0.35;
          const ex = targetX - p.x;
          axDes = clamp(9.5 * ex - 3.8 * v.x + 1.4 - windFast.x - 0.45 * gustRateX, -4.5, 4.8);
        }
      } else {
        const pad = obs.pad.centre;
        const ex = pad.x - p.x;
        const ez = pad.z - p.z;
        const distXZ = Math.hypot(ex, ez);
        const speedXZ = Math.hypot(v.x, v.z);
        const speed3D = Math.hypot(v.x, v.y, v.z);

        if (p.y <= 0.088 && distXZ <= 0.135 && speed3D < 0.65) {
