      const rawAct = ctrl.step(obs);
      const act = { thrust: clamp(rawAct.thrust, 0, 1), roll: clamp(rawAct.roll, -0.6, 0.6), pitch: clamp(rawAct.pitch, -0.6, 0.6), yawRate: clamp(rawAct.yawRate, -2, 2) };
