          const yUnsafe = Math.abs(yPred - gate.y) > 0.095 || Math.abs(dyGate) > 0.095;
          const canBrake = dxGate > stopDistX + 0.02 && dxGate > 0.055;

          if ((zUnsafe || yUnsafe) && canBrake) {
            phase = 'align';
            settle = 0;
          }
        }

        if (Math.abs(dzGate) < 0.10 && Math.abs(dxGate) < 0.42) {
          intZ = clamp(intZ + dzGate * DT, -0.25, 0.25);
        } else {
          intZ *= 0.92;
        }
        if (Math.abs(dyGate) < 0.20) {
          intY = clamp(intY + dyGate * DT, -0.35, 0.35);
        }

        if (Math.abs(dzGate) > 0.16) {
          const vzDes = smoothProfileVel(dzGate, 1.55, 2.4, 4.6);
          azDes = 6.5 * (vzDes - vz) - windFast.z - 0.30 * gustDeltaZ;
        } else {
          azDes = 15.5 * dzGate - 7.0 * vz + 3.8 * intZ - windFast.z - 0.35 * gustDeltaZ;
        }
        azDes = clamp(azDes, -5.5, 5.5);

        const vyDes = smoothProfileVel(dyGate, 1.50, 2.5, 4.6);
        ayDes = clamp(6.4 * (vyDes - vy) + 2.2 * intY, -4.5, 5.5);

        if (dxGate <= 0.0) {
          if (Math.abs(dzGate) < 0.016 && Math.abs(dyGate) < 0.07) {
            const targetX = gate.x - 0.20;
            const vxDes = smoothProfileVel(targetX - p.x, 0.70, 1.8, 3.5);
            axDes = 5.5 * (vxDes - vx) - windFast.x;
          } else {
            const targetX = gate.x + 0.12;
            const vxDes = smoothProfileVel(targetX - p.x, 0.60, 1.8, 3.5);
            axDes = 5.5 * (vxDes - vx) - windFast.x;
          }
          axDes = clamp(axDes, -4.5, 4.5);
        } else if (phase === 'align') {
          const zUnaligned = Math.abs(dzGate) > 0.032 || Math.abs(vz) > 0.20;
          const standOff = zUnaligned ? (0.25 + clamp(0.40 * Math.abs(dzGate), 0, 0.20)) : 0.16;
          const targetX = gate.x - standOff;
          const ex = targetX - p.x;
          const maxVx = Math.abs(dzGate) > 0.15 ? 1.15 : 1.50;
          const vxDes = smoothProfileVel(ex, maxVx, 1.9, 4.2);
          axDes = 5.8 * (vxDes - vx) - windFast.x - 0.30 * gustDeltaX;

          if (dxGate < stopDistX + 0.09 && (Math.abs(dzGate) > 0.019 || Math.abs(zPred - gate.z) > 0.021 || Math.abs(dyGate) > 0.08)) {
            axDes = Math.min(axDes, -5.0 - windFast.x);
          }
          axDes = clamp(axDes, -5.4, 4.5);
        } else {
          const targetX = gate.x + 0.32;
          const ex = targetX - p.x;
          const vxDes = clamp(5.2 * ex + 0.65, 0.85, 1.65);
          axDes = clamp(6.6 * (vxDes - vx) - windFast.x - 0.30 * gustDeltaX, -4.5, 5.0);
        }

        if (lastGate !== null && p.x > lastGate.x - 0.02 && p.x < lastGate.x + 0.15) {
          const minVx = 0.60;
          if (vx < minVx) {
            axDes = Math.max(axDes, 6.5 * (minVx - vx) - windFast.x);
          }
        }
      } else {
        const pad = obs.pad.centre;
        const ex = pad.x - p.x;
        const ez = pad.z - p.z;
        const distXZ = Math.hypot(ex, ez);
        const speedXZ = Math.hypot(velEst.x, velEst.z);
        const speed3D = Math.hypot(velEst.x, velEst.y, velEst.z);

        if (p.y <= 0.090 && distXZ <= 0.138 && speed3D < 0.60) {
          padPinned = true;
        }
        if (padPinned && (distXZ > 0.146 || p.y > 0.11)) {
          padPinned = false;
        }

        if (padPinned) {
          lowThrustPin = true;
          maxTilt = 0.13;
          axDes = clamp(8.0 * ex - 4.0 * velEst.x - 0.65 * windFast.x, -2.2, 2.2);
          azDes = clamp(8.0 * ez - 4.0 * velEst.z - 0.65 * windFast.z, -2.2, 2.2);
          ayDes = -6.0;
        } else {
          if (distXZ < 0.16) {
            intZ = clamp(intZ + ez * DT, -0.25, 0.25);
          } else {
            intZ *= 0.95;
          }

          const vxDes = smoothProfileVel(ex, 1.55, 2.2, 4.4);
          const vzDes = smoothProfileVel(ez, 1.55, 2.2, 4.4);
          axDes = clamp(6.0 * (vxDes - velEst.x) - windFast.x - 0.30 * gustDeltaX, -4.8, 4.8);
          azDes = clamp(6.0 * (vzDes - velEst.z) + 2.2 * intZ - windFast.z - 0.30 * gustDeltaZ, -4.8, 4.8);

          if (p.x < 1.48 && velEst.x < 0.55) {
            axDes = Math.max(axDes, 5.5 * (0.55 - velEst.x) - windFast.x);
          }

          let targetY;
          if (distXZ > 0.115 || (p.y < 0.18 && speedXZ > 0.32)) {
            targetY = clamp(0.11 + 0.50 * distXZ, 0.11, 0.85);
          } else {
            targetY = 0.01;
          }

          const ey = targetY - p.y;
          let maxDownV = p.y > 0.26 ? -1.05 : (p.y > 0.15 ? -0.42 : -0.24);
          let vyDes = clamp(4.2 * ey, maxDownV, 1.5);
          if (p.y < 0.15 && targetY < 0.10) {
            maxTilt = 0.26;
          }
          if (p.y < 0.105 && targetY < 0.10) {
            maxTilt = 0.15;
          }
          ayDes = clamp(6.5 * (vyDes - velEst.y), -4.5, 4.8);
        }
      }

      if (p.x < -2.45 && velEst.x < -0.3) axDes = Math.max(axDes, 6.0 * (-0.2 - velEst.x) - windFast.x);
      if (p.x > 2.45 && velEst.x > 0.3) axDes = Math.min(axDes, 6.0 * (0.2 - velEst.x) - windFast.x);
      if (p.z < -2.45 && velEst.z < -0.3) azDes = Math.max(azDes, 6.0 * (-0.2 - velEst.z) - windFast.z);
      if (p.z > 2.45 && velEst.z > 0.3) azDes = Math.min(azDes, 6.0 * (0.2 - velEst.z) - windFast.z);
      if (p.y > 2.65 && velEst.y > 0.2) ayDes = Math.min(ayDes, 6.0 * (0.1 - velEst.y));

      const aTx = axDes + cd * velEst.x;
      const aTz = azDes + cd * velEst.z;
      const aTy = Math.max(2.0, 9.81 + cd * velEst.y + ayDes);

      const cy = Math.cos(att.yaw);
      const sy = Math.sin(att.yaw);
      const fx = cy * aTx - sy * aTz;
      const fz = sy * aTx + cy * aTz;

      const cosCurPitch = Math.max(0.6, Math.cos(att.pitch));
      let pitchDes = clamp(Math.atan2(fx, aTy), -maxTilt, maxTilt);
      let rollDes = clamp(-Math.atan2(fz * cosCurPitch, aTy), -maxTilt, maxTilt);

      let thrust;
      if (lowThrustPin) {
        thrust = 0.08;
      } else {
        const cosTilt = Math.max(0.5, Math.cos(att.roll) * Math.cos(att.pitch));
        thrust = clamp(aTy / (thrustScale * cosTilt), 0.05, 1.0);
      }

      const rawRollRate = clamp((rollDes - prevRollDes) / DT, -3.0, 3.0);
      const rawPitchRate = clamp((pitchDes - prevPitchDes) / DT, -3.0, 3.0);
      rollRateEst += 0.30 * (rawRollRate - rollRateEst);
      pitchRateEst += 0.30 * (rawPitchRate - pitchRateEst);
      prevRollDes = rollDes;
      prevPitchDes = pitchDes;

      const kpAtt = 74;
      const kdAtt = 16.5;
      const alphaRollDes = kpAtt * (rollDes - att.roll) - kdAtt * rateEst.roll + 6.0 * rollRateEst;
      const alphaPitchDes = kpAtt * (pitchDes - att.pitch) - kdAtt * rateEst.pitch + 6.0 * pitchRateEst;

      const biasRoll = beta.roll * thrust + bRes.roll;
      const biasPitch = beta.pitch * thrust + bRes.pitch;
      const biasYaw = beta.yaw * thrust + bRes.yaw;

      const uAlphaRoll = alphaRollDes + 0.4 * rateEst.roll - biasRoll;
      const uAlphaPitch = alphaPitchDes + 0.4 * rateEst.pitch - biasPitch;

      const rollCmd = clamp(att.roll + (uAlphaRoll + 13 * rateEst.roll - 22 * simInt.roll) / 65.165, -0.6, 0.6);
      const pitchCmd = clamp(att.pitch + (uAlphaPitch + 13 * rateEst.pitch - 22 * simInt.pitch) / 65.165, -0.6, 0.6);

      const alphaYawDes = -14 * att.yaw - 5.5 * rateEst.yaw;
      const yawRateCmd = clamp(rateEst.yaw + (alphaYawDes + 0.4 * rateEst.yaw - biasYaw) / 8, -2, 2);

      const action = {
        thrust,
        roll: rollCmd,
        pitch: pitchCmd,
        yawRate: yawRateCmd,
      };

      prevObs = obs;
      prevAction = action;
      return action;
    },
  };
}
