          const predVx = velEst.x + (specThrust * dirX - cd * velEst.x + windFast.x) * DT;
          const predVz = velEst.z + (specThrust * dirZ - cd * velEst.z + windFast.z) * DT;
          const errVx = v.x - predVx;
          const errVz = v.z - predVz;
          velEst.x = predVx + 0.42 * errVx;
          velEst.z = predVz + 0.42 * errVz;

          windFast.x = clamp(windFast.x + 5.2 * errVx, -12, 12);
          windFast.z = clamp(windFast.z + 5.2 * errVz, -12, 12);
          windSlow.x += 0.04 * (windFast.x - windSlow.x);
          windSlow.z += 0.04 * (windFast.z - windSlow.z);
        } else {
          velEst.x = v.x; velEst.y = v.y; velEst.z = v.z;
        }
      }

      const estMass = clamp(15.3 / thrustScale, 0.6, 0.95);
